        "description": "Голубая пижма помогает преодолевать сопротивление покоя и начинать действовать для изменения и преображения сложившихся обстоятельств. Особенно выручает она стагнировавших в развитии, высекая своего рода каталитическую искру преодоления склонностей к колебаниям, стремлению отсидеться в сторонке и прокрастинациям. Голубая пижма вынуждает набраться решимости взять на себя ответственность за свою жизнь, побуждая жить в согласии с шёпотом внутреннего голоса и сподвигая на давно назревшие изменения. Подавляя же такие призывы, человек часто впадает в летаргию, чувствуя себя выпотрошенным, апатичным, вялым и измождённым. Голубая пижма призывает, проявив инициативу, вернуть себе жизнь своей мечты.\n\nЭфирное масло голубой пижмы станет манифестом к действию, когда соблазн отступить уже непреодолим и в моменты самосаботажа. Вырабатывая больше внутренней мобильности, голубая пижма подстрекает к принятию чего бы то ни было, в том числе эмоциональных неудач и разных, подлежащих преодолению вызовов во имя воплощения своего вдохновения и поддержки жизненных изменений. Этот аромат учит, что за каждым действием стоит выбор, требуя взять на себя ответственность за свой выбор совокупный. Ещё он требует личного мастерства наряду с целенаправленными действиями для полноценной реализации своего потенциала.",
