        "description": "Масло мелиссы пробуждает душу к истине и свету. Напоминая людям о том, кто они есть на самом деле и зачем пришли на этот свет. Мелисса предлагает человеку отпустить то всё и вся, что препятствует полному раскрытию своего потенциала.\n\nЭфирное масло мелиссы помогает личности получать духовное руководство, воссоединяя её со своим внутренним голосом. Через чувство душевного подъёма подводя человека к возвышению. Когда кто-то чувствует себя слишком придавленным бременем жизни, мелисса призывает продолжать движение. Вдыхает жизнь и силу в самые сокровенные уголки души и сердца. Это масло приглашает подключиться к высшим сферам жизни и мечтаний. Будучи на связи с духовными источниками, люди всем существом ощущают лёгкость и яркость в своей сущности. Мелисса во всеуслышание напоминает, что в каждом человеке теплится божественная искра, разгорающаяся лишь ярче от любви и внимания. Будучи топливом для той искорки, масло это воспламеняет Истинное Я человека. Мелисса помогает избавляться от всего, что не находится в гармонии со своим внутренним светом.\n\nЭнтузиазм аромата мелиссы так заразителен, что её высокие вибрации и яркий свет не оставляет никакого другого выбора, кроме как отпустить чувства тьмы, отчаяния и прочих давящих низких вибраций. Она учит радости жизни.",
