        "description": "Пачули помогает вернуться в своё тело здесь и сейчас. Уравновешивает чувствующих свою нежизнеспособность или стремящихся избегать своего тела, уходя в духовные практики и другие формы отвлечения от действительности. Пачули сдерживает одержимых, возвращая их к реальности и обучая умеренности. Это заземляющее и стабилизирующее масло.\n\nЭфирное масло пачули прекрасно дополняет практики йоги, тай-чи и другие, направленные на воссоединение Духа с телом упражнения. Применяя пачули, человек чувствует себя более заземленными и подвижным. Это масло успокаивает страхи и снимает нервное напряжение, даруя успокоение и уму, и сердцу, а дух и тело подготавливая к тесному единению. Возвращает человека на землю.\n\nАромат пачули позволяет людям в полной мере оценить великолепие своего физического тела со всеми его природными процессами и функциями. Помогает высвободить связанные с телом эмоциональные суждения и проблемы, в частности веру в то, что тело нечестиво или грязно. Этот аромат помогает от привитых искажений в восприятии образа тела и общей неприязни к телу. Пачули несёт уверенность в теле, а вместе с нею и грацию, уравновешенность и физическую силу. Напоминает человеку о детской поре, когда он к телу обращался играючи и забавляясь. Пачули на глубинном уровне помогает личности почувствовать себя спокойно, находясь в своем физическом теле.",
