        "application": "Ароматическое: вдыхать непосредственно из флакона или растерев в ладонях, распылять в диффузоре перед молитвой, учебой, медитацией.\nМестное нанесение: 1 каплю на лоб или темя.\n\nПРИМЕЧАНИЕ: Сандала два вида: гавайский и индийский. Оба раскрывают шестую (бровную) чакру. Однако сандал гавайский считается подходящим для верхних чакр, тогда как индийский издревле способствовал глубинному заземлению нижних. Тот и другой - превосходные масла для медитаций и духовных практик."
