        {
          "hormone": "Для зачатия малыша",
          "text": "Неспособность зачать может быть вызвана разными причинами, и не все их можно устранить с помощью ароматерапии. Однако, есть несколько областей, в которых эфирные масла могут быть очень полезны. Часто бесплодие связано с нерегулярными и скудными менструациями, когда трудно определить время овуляции. Масло розы имеет особую связь с женской репродуктивной системой, оно тонизирует и очищает матку. Оно очень эффективно для регулирования цикла, так как оказывает воздействие и на яичники, и на матку. Было обнаружено, что роза также способствует увеличению количества спермы у мужчин, поэтому паре, пытающейся зачать ребенка, будет полезно использовать масло розы для массажа и ванн. Герань — еще одно масло, гармонизирующее гормональный фон и способствующее налаживанию (текст в источнике обрывается). Неудачные попытки зачать ребенка вызывают стресс и напряженность в отношениях, а это, в свою очередь, препятствует зачатию. Этот порочный круг помогут разорвать регулярный массаж и ванны с (текст в источнике обрывается). Я рекомендую чередовать и комбинировать масла шалфея мускатного, жасмина, нероли, розы, сандалового (текст в источнике обрывается, вероятно «...дерева»)."
        }
