        "description": "Садовая мята вносит ясность в мысли, помогая внятно их формулировать. Испытывающий потребность в ней человек может бесконечно держать своё мнение, идеи и мысли при себе, словно язык проглотив. Садовая мята вдохновляет расставить точки над \"Ё,\" касательно своих личных убеждений и мнений. Вслед за чем помогает людям внятно оформить эту внутреннюю ясность в речь.\n\nЭфирное масло садовой мяты способствует уверенному вербальному самовыражению, в том числе и на публике. Вселяет столь необходимую для эффектной подачи себя со сцены уверенность. Помогает человеку занять общественную позицию в интересах своего мнения и ценностей.\n\nАромат садовой мяты поможет, преодолев все препоны, наконец научиться говорить внятно и без запинки - будь то робость, путаная речь или неразвитая дикция. Прежде всего, он поможет человеку прояснить эмоционально то, что тот хотел сказать, а затем и высказаться. Другими словами - садовая мята способствует личности, обретя свой внутренний свет, пролить его лучи во внешний мир уверенно и ясно.",
