        "description": "Мандарин своим напором радости способен поднимать самые мрачные настроения. Выручая утративших детскую способность жить с лёгким сердцем людей. Гиперответственные натуры только выиграют от жизнеутверждающих мандариновых вибраций. Он заряжает личность творчеством и спонтанностью.\n\nВедь творчество напрочь отбивается гипертрофированным чувством долга или ужесточением требований к себе. Когда имеют место работа, долг и ответственность, чувство переутомления, гиперответственности и перегруженности приводит к утрате творческой энергии. Эфирное масло мандарина приглашает людей высвободить место в жизни и для своей творческой стороны с тем, чтобы снова впустить в жизнь веселье, радость и спонтанность.\n\nАромат мандарина помогает личности добраться до неиссякаемого источника творческой энергии своего духа. Вслед за чем помогает направить поток этой энергии через сердце в физические проявления. Мандарин учит людей наслаждаться жизнью через творческое изобилие, а детские радость и ликование от неё переживать вновь и вновь.",
