        "description": "Куркума восстанавливает людей физически, умственно и эмоционально. Обладая мощными, способными достигать поврежденных или заблокированных аспектов личности свойствами, она может восстановить то, что было на время утрачено. Куркума - сильное противоядие для того, кто чувствует себя парализованным теми или иными присущими жизни опасностями, как и утратой некоей своей функции или свободы, наличие которой казалось когда-то само собой разумеющимися. Особенно выручает она, когда человек чувствует себя угнетённым личной трагедией или потерей уверенности в своих силах. Куркума придаёт человеку сил и надежды устоять на ногах во времена потрясений или больших перемен.\n\nЭфирное масло куркумы поможет восстановить и веру в добро. Напоминая, что к лучшему или к худшему, но каждому отведена своя уникальная роль в мировой книге судеб. В пору, когда совершаются зверства и бессердечные события разворачиваются безо всякого смысла или видимых тому причин, вид чужих злодеяний может пошатнуть всякую веру в человечество. Куркума восстанавливает веру в то, что большинство людей, всё же, выбирают быть посланниками добра, не пугаясь связанных с этим рисков. Сообщая колеблющемуся сердцу стабильность, мощное, обогревающее тепло куркумы укрепляет фундамент доверия в способности человека к добру, и существование возможностей для развития.\n\nАромат куркумы также помогает преодолевать такие препятствия системы, как предрассудки, предвзятость и расизм, помогая людям распознавать диссонирующие или дискредитирующие послания, отличая ложь от истины. Куркума наполняет душу мужеством, придавая сил превратить то, что на первый взгляд кажется непобедимыми препятствиями в судоходные пути.",
