        "description": "Дикий апельсин решает самые разнообразные эмоциональные проблемы. Способствует изобилию, вдохновляет на творчество и поддерживает положительный настрой. Дикий Апельсин также воссоединяет человека с его внутренним ребёнком, чем привносит в его жизнь спонтанность, веселье, радость и игривость.\n\nВ основе своей эфирное масло дикого апельсина учит истинному смыслу изобилия. Побуждая людей отказаться от самих мыслей о накопительстве со всеми его проявлениями, включая страх, нервозность, неподатливость, трудоголизм, отсутствие чувства юмора и настрой на постоянную нехватку. Дикий апельсин напоминает душе о безграничных природных богатствах. Ведь и апельсиновое, и другие фруктовые деревья щедро одаривают всех нуждающихся. Масло это учит людей отдавать, не задумываясь о компенсации. Ибо у матушки-природы на всех хватит. Дикий апельсин вдохновляет людей отпускать присущую им потребность в накопительстве, которая по сути своей и является воплощением бедности.\n\nПробуждает аромат дикого апельсина и естественные творческие чувства личности. Например, вдохновляя на безграничное множество вариантов решения проблем и задач. Вовсе нет нужды жить в страхе - никогда. Дикий апельсин предлагает личности научиться всецело отпускать, как это делает ребенок, и жить от своего Истинного Я. Ибо изобилие заложено в основе самой человеческой природы. Делиться, играть, раскрепощаться и наслаждаться щедротами жизни - вот подарки, дарованные маслом дикого апельсина.",
