        "description": "Грушанка - это масло смирения. Она способна помочь волевым людям освободиться от потребности знать обо всём и необходимости быть всегда правыми. Ибо стоит недюжинных внутренних усилий сдаться на милость Высшей Силе. Наполняя душу такой силой, грушанка научит, как отпускать и освобождаться от негатива и боли, что человек носит в себе. Вера в то, что жизнь - боль, которую нужно, непременно страдая, преодолевать в одиночку тому причина. Грушанка предлагает людям отказаться от подобных канонизированных устоев.\n\nЭфирное масло грушанки напоминает человеку о том, что не обязательно до конца дней своих в одиночку нести бремя жизни. Ибо возможность переложить своё бремя на плечи Высшей Силе всегда открыта. Всё, что от него требуется - это высвободить и отпустить. Аромат грушанки учит, что отныне можно передать свои трудности этой превосходящей силе, дабы впредь не носить бремя жизни в одиночку.",
